// This code has been fully generated by an AI.
import { after, before, test } from 'node:test';
import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { chromium } from 'playwright';

let server;
let browser;
let url;

before(async () => {
  const component = await readFile(new URL('../src/components/CookieConsent.astro', import.meta.url), 'utf8');
  const script = component.match(/<script is:inline>([\s\S]*?)<\/script>/)?.[1];
  assert.ok(script, 'Cookie consent script must exist');

  server = createServer((request, response) => {
    response.writeHead(200, { 'content-type': 'text/html' });
    response.end(`<!doctype html>
      <button id="before">Page content</button>
      <div style="height: 3000px"></div>
      <button data-cookie-preferences>Cookie settings</button>
      <section data-cookie-banner hidden style="position: fixed; bottom: 0; background: white">
        <button data-cookie-accept>Accept</button>
        <button data-cookie-reject>Reject</button>
        <button data-cookie-settings>Settings</button>
        <div data-cookie-settings-panel hidden>
          <input type="checkbox" data-cookie-analytics>
          <button data-cookie-save>Save</button>
        </div>
      </section>
      <script>${script}</script>`);
  });
  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
  url = `http://127.0.0.1:${server.address().port}/`;
  browser = await chromium.launch({ headless: true });
});

after(async () => {
  await browser?.close();
  if (server) await new Promise((resolve, reject) => server.close((error) => error ? reject(error) : resolve()));
});

for (const [action, choice] of [
  ['accept', 'analytics'],
  ['reject', 'necessary'],
  ['save', 'necessary'],
]) {
  test(`${action} preserves scroll position and consent`, async () => {
    const page = await browser.newPage({ viewport: { width: 390, height: 800 } });
    try {
      await page.route('https://www.googletagmanager.com/**', (route) => route.abort());
      await page.goto(url);
      if (action === 'save') await page.locator('[data-cookie-settings]').click();
      const before = await page.evaluate(() => window.scrollY);
      await page.locator(`[data-cookie-${action}]`).click();
      assert.equal(await page.evaluate(() => window.scrollY), before);
      assert.equal(await page.evaluate(() => localStorage.getItem('semrel-cookie-consent')), choice);
      assert.equal(await page.locator('[data-cookie-banner]').isHidden(), true);
    } finally {
      await page.close();
    }
  });
}

test('reopened settings restore focus to the footer control without scrolling', async () => {
  const page = await browser.newPage({ viewport: { width: 390, height: 800 } });
  try {
    await page.goto(url);
    await page.locator('[data-cookie-reject]').click();
    await page.locator('[data-cookie-preferences]').click();
    await page.evaluate(() => window.scrollTo(0, 0));
    const before = await page.evaluate(() => window.scrollY);
    await page.locator('[data-cookie-save]').click();
    assert.equal(await page.evaluate(() => window.scrollY), before);
    assert.equal(await page.evaluate(() => document.activeElement.hasAttribute('data-cookie-preferences')), true);
  } finally {
    await page.close();
  }
});

test('initial banner restores focus to the previously focused page control', async () => {
  const page = await browser.newPage({ viewport: { width: 390, height: 800 } });
  try {
    await page.goto(url);
    await page.locator('#before').focus();
    await page.locator('[data-cookie-reject]').click();
    assert.equal(await page.evaluate(() => document.activeElement.id), 'before');
    assert.equal(await page.evaluate(() => window.scrollY), 0);
  } finally {
    await page.close();
  }
});
